import{_ as e,c as t,o as s,ag as n}from"./chunks/framework.Vyheyqg9.js";const p=JSON.parse('{"title":"Do you know some of the differences of non relational databases and relational databases?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/EngX_Quality/Do_you_know_some_of_the_differences_of_non_relational_databases_and_relational_databases.md","filePath":"senior_growth/EngX_Quality/Do_you_know_some_of_the_differences_of_non_relational_databases_and_relational_databases.md"}'),o={name:"senior_growth/EngX_Quality/Do_you_know_some_of_the_differences_of_non_relational_databases_and_relational_databases.md"};function r(i,a,l,d,c,g){return s(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="do-you-know-some-of-the-differences-of-non-relational-databases-and-relational-databases" tabindex="-1">Do you know some of the differences of non relational databases and relational databases? <a class="header-anchor" href="#do-you-know-some-of-the-differences-of-non-relational-databases-and-relational-databases" aria-label="Permalink to “Do you know some of the differences of non relational databases and relational databases?”">​</a></h1><p>Yes, relational databases (RDBMS) and non-relational databases (NoSQL) differ in several key aspects related to their data models, structure, scalability, and usage. Here’s a comparison:</p><h3 id="_1-data-model" tabindex="-1"><span class="hub-section-number">1 </span><strong>Data Model</strong> <a class="header-anchor" href="#_1-data-model" aria-label="Permalink to “1 Data Model”">​</a></h3><ul><li><strong>Relational Databases (RDBMS)</strong>: <ul><li><strong>Structured Data</strong>: Data is stored in tables with predefined schemas consisting of rows and columns.</li><li><strong>Schema-based</strong>: Uses declared types/constraints that can evolve through migrations. Foreign keys can enforce relationships; JSON columns can hold semistructured data.</li><li><strong>Examples</strong>: MySQL, PostgreSQL, Oracle, Microsoft SQL Server.</li></ul></li><li><strong>Non-relational Databases (NoSQL)</strong>: <ul><li><strong>Flexible Schema</strong>: Can handle unstructured, semi-structured, or structured data. Some NoSQL databases are schema-less or allow dynamic schema.</li><li><strong>Data Types</strong>: NoSQL databases support various models like key-value pairs, document stores, wide-column stores, and graph databases.</li><li><strong>Examples</strong>: MongoDB (document), Cassandra (wide-column), Redis (key-value), Neo4j (graph).</li></ul></li></ul><hr><h3 id="_2-data-structure" tabindex="-1"><span class="hub-section-number">2 </span><strong>Data Structure</strong> <a class="header-anchor" href="#_2-data-structure" aria-label="Permalink to “2 Data Structure”">​</a></h3><ul><li><strong>Relational Databases (RDBMS)</strong>: <ul><li><strong>Tables</strong>: Data is stored in tables with rows (records) and columns (attributes).</li><li><strong>Relationships</strong>: Supports relationships between tables using <strong>Primary Keys</strong> and <strong>Foreign Keys</strong>.</li><li><strong>Normalization</strong>: Data is typically normalized to minimize redundancy and ensure data integrity.</li></ul></li><li><strong>Non-relational Databases (NoSQL)</strong>: <ul><li><strong>Key-Value Stores</strong>: Data is stored as key-value pairs, useful for fast lookups.</li><li><strong>Document Stores</strong>: Data is stored as documents (often JSON or BSON), which can have nested structures.</li><li><strong>Wide-Column Stores</strong>: Data is stored in rows and columns, but columns are grouped into families, providing more flexibility.</li><li><strong>Graph Databases</strong>: Data is stored in graphs with nodes, edges, and properties, used for connected data.</li><li><strong>Flexible Schema</strong>: NoSQL databases can store data without a fixed schema, which can be beneficial for evolving datasets.</li></ul></li></ul><hr><h3 id="_3-scalability" tabindex="-1"><span class="hub-section-number">3 </span><strong>Scalability</strong> <a class="header-anchor" href="#_3-scalability" aria-label="Permalink to “3 Scalability”">​</a></h3><ul><li><strong>Relational Databases (RDBMS)</strong>: <ul><li><strong>Scaling options</strong>: Vertical resources, indexes/query design, replicas, partitioning and, for suitable products/designs, sharding/distributed SQL.</li><li><strong>Trade-offs</strong>: Cross-partition joins/transactions, replication lag, hotspots and operational cost depend on product/topology/workload.</li></ul></li><li><strong>Non-relational Databases (NoSQL)</strong>: <ul><li><strong>Horizontal scaling</strong>: Some products support native distribution; partition-key design, hotspots and coordination still constrain throughput.</li><li><strong>Workload fit</strong>: Document/key-value/graph access patterns may fit a given workload; category labels do not establish lower latency or cost.</li></ul></li></ul><hr><h3 id="_4-consistency-and-transactions" tabindex="-1"><span class="hub-section-number">4 </span><strong>Consistency and Transactions</strong> <a class="header-anchor" href="#_4-consistency-and-transactions" aria-label="Permalink to “4 Consistency and Transactions”">​</a></h3><ul><li><strong>Relational Databases (RDBMS)</strong>: <ul><li><strong>ACID Compliance</strong>: RDBMS follow <strong>ACID</strong> (Atomicity, Consistency, Isolation, Durability) principles to ensure reliable transactions.</li><li><strong>Isolation/replication</strong>: Guarantees depend on the isolation level and read path; a lagging replica or Read Committed transaction is not universally linearizable/serializable.</li><li><strong>Transactions</strong>: Supports complex transactions with multiple operations that can be rolled back if needed.</li></ul></li><li><strong>Non-relational Databases (NoSQL)</strong>: <ul><li><strong>Configurable guarantees</strong>: Products differ. MongoDB exposes read/write concerns and distributed transactions; some deployments/read choices allow stale or rollback-prone observations.</li><li><strong>CAP</strong>: During network partitions, a system cannot guarantee both linearizable reads/writes and successful service of every request at nonfailing nodes. This applies to distributed SQL and NoSQL; it does not label all NoSQL as AP.</li><li><strong>Transactions</strong>: MongoDB supports multi-document transactions across collections/shards under supported deployment/settings; Neo4j provides ACID transactions. Check actual scope/isolation/durability rather than assuming no comparable transactions.</li></ul></li></ul><hr><h3 id="_5-querying-and-flexibility" tabindex="-1"><span class="hub-section-number">5 </span><strong>Querying and Flexibility</strong> <a class="header-anchor" href="#_5-querying-and-flexibility" aria-label="Permalink to “5 Querying and Flexibility”">​</a></h3><ul><li><strong>Relational Databases (RDBMS)</strong>: <ul><li><strong>SQL</strong>: Uses <strong>Structured Query Language (SQL)</strong> for querying, which is powerful and standardized across relational systems.</li><li><strong>Complex Queries</strong>: RDBMS are ideal for complex queries with multiple joins, subqueries, and aggregations.</li><li><strong>Declared schema</strong>: Migrations/constraints make structure explicit; model evolution and JSON support remain available.</li></ul></li><li><strong>Non-relational Databases (NoSQL)</strong>: <ul><li><strong>Varied Query Languages</strong>: NoSQL databases have different query languages and methods depending on the database type (e.g., MongoDB uses a query language that operates on documents, while Redis uses simple key-based queries).</li><li><strong>Schema-less</strong>: NoSQL allows for flexible data models that can evolve over time, which is useful for applications with rapidly changing data.</li><li><strong>Query fit</strong>: Join/aggregation/traversal capabilities vary; graph traversal may be more natural in a graph store, while document embedding changes update/query trade-offs.</li></ul></li></ul><hr><h3 id="_6-use-cases" tabindex="-1"><span class="hub-section-number">6 </span><strong>Use Cases</strong> <a class="header-anchor" href="#_6-use-cases" aria-label="Permalink to “6 Use Cases”">​</a></h3><ul><li><strong>Relational Databases (RDBMS)</strong>: <ul><li><strong>Best for structured data</strong>: Applications that require structured data and relationships, such as financial systems, ERP systems, and transactional applications.</li><li><strong>Strong Data Integrity</strong>: Ideal for applications that require strong consistency and ACID transactions (e.g., banking, inventory systems).</li></ul></li><li><strong>Non-relational Databases (NoSQL)</strong>: <ul><li><strong>Big Data</strong>: Well-suited for handling large volumes of unstructured or semi-structured data, such as social media platforms, IoT data, and logs.</li><li><strong>Real-Time Applications</strong>: Often used in applications that require fast data ingestion and retrieval, such as real-time analytics, recommendation engines, and content management systems.</li><li><strong>Flexible and Evolving Data</strong>: Ideal for applications with evolving data structures, where the schema may change over time, like e-commerce platforms, content management, and social media apps.</li></ul></li></ul><hr><h3 id="_7-performance" tabindex="-1"><span class="hub-section-number">7 </span><strong>Performance</strong> <a class="header-anchor" href="#_7-performance" aria-label="Permalink to “7 Performance”">​</a></h3><ul><li><strong>Relational Databases (RDBMS)</strong>: <ul><li><strong>Optimized for Transactional Workloads</strong>: RDBMS are optimized for transactional workloads where data integrity is critical.</li><li><strong>Complex Queries</strong>: RDBMS tend to perform well for complex queries, aggregations, and data analysis.</li></ul></li><li><strong>Non-relational Databases (NoSQL)</strong>: <ul><li><strong>Distribution costs</strong>: A partitionable workload can scale on a suitable product, but balancing, coordination and failure recovery must be designed/tested.</li><li><strong>Write behavior</strong>: Indexes, acknowledgment/durability settings, contention and replication determine latency/throughput; measure against the required guarantees.</li></ul></li></ul><hr><h3 id="_8-examples-and-specifics" tabindex="-1"><span class="hub-section-number">8 </span><strong>Examples and Specifics</strong> <a class="header-anchor" href="#_8-examples-and-specifics" aria-label="Permalink to “8 Examples and Specifics”">​</a></h3><ul><li><strong>Relational Databases (RDBMS)</strong>: <ul><li><strong>MySQL</strong>: Popular for web applications and content management systems.</li><li><strong>PostgreSQL</strong>: Known for its strong consistency and extensibility, used in analytics, geospatial data, and more.</li><li><strong>Oracle Database</strong>: Enterprise-level RDBMS widely used for business applications with complex requirements.</li></ul></li><li><strong>Non-relational Databases (NoSQL)</strong>: <ul><li><strong>MongoDB</strong>: A document store with explicit document/index/distribution and read/write-concern choices.</li><li><strong>Cassandra</strong>: A distributed, wide-column store designed for high availability and massive scalability.</li><li><strong>Redis</strong>: A fast, in-memory key-value store often used for caching, session storage, and real-time analytics.</li><li><strong>Neo4j</strong>: A graph database used to store data in a graph format (e.g., for social networks, fraud detection).</li></ul></li></ul><hr><h3 id="summary-table" tabindex="-1"><span class="hub-section-number">9 </span><strong>Summary Table</strong> <a class="header-anchor" href="#summary-table" aria-label="Permalink to “9 Summary Table”">​</a></h3><table tabindex="0"><thead><tr><th><strong>Aspect</strong></th><th><strong>Relational Databases (RDBMS)</strong></th><th><strong>Non-relational Databases (NoSQL)</strong></th></tr></thead><tbody><tr><td><strong>Data Structure</strong></td><td>Tables, rows, columns</td><td>Flexible structures (documents, key-value, graphs, wide-column)</td></tr><tr><td><strong>Schema</strong></td><td>Declared/evolvable; JSON possible</td><td>Product-specific validation/evolution</td></tr><tr><td><strong>Query Language</strong></td><td>SQL</td><td>Varies (depends on DB type)</td></tr><tr><td><strong>Scalability</strong></td><td>Product/topology/partition/query dependent</td><td>Product/topology/partition/query dependent</td></tr><tr><td><strong>Consistency</strong></td><td>Isolation/read-replica choices matter</td><td>Read/write concerns and topology matter</td></tr><tr><td><strong>Transactions</strong></td><td>Usually multi-row/table transactions; check isolation</td><td>Some support ACID multi-record transactions; check scope/settings</td></tr><tr><td><strong>Selection</strong></td><td>Choose invariant/query/isolation/topology fit</td><td>Choose invariant/query/isolation/topology fit</td></tr><tr><td><strong>Examples</strong></td><td>MySQL, PostgreSQL, Oracle</td><td>MongoDB, Cassandra, Redis, Neo4j</td></tr></tbody></table><hr><h2 id="choose-guarantees-for-a-concrete-workload" tabindex="-1"><span class="hub-section-number">10 </span>Choose guarantees for a concrete workload <a class="header-anchor" href="#choose-guarantees-for-a-concrete-workload" aria-label="Permalink to “10 Choose guarantees for a concrete workload”">​</a></h2><p>ACID consistency means preserving declared invariants through valid transactions; it is not CAP&#39;s linearizability. Availability in the CAP model is not the same as a monthly uptime SLO or returning an error response. A deployment can deliberately reject an isolated partition&#39;s writes to protect its consistency contract. Eventual convergence requires its own conflict/repair assumptions and does not mean every database operation is equally stale.</p><p>For the primary inventory learning app, PostgreSQL16 is a coherent default: explicit product/tenant/SKU constraints, atomic stock changes and transactional use cases. MongoDB remains a substantive alternative exercise when the document aggregate/access pattern is appropriate; Neo4j is an introduction to graph-oriented trade-offs, not an additional required production stack. NoSQL still needs schema validation, indexes, migration/backfill strategy and tested backups.</p><p><strong>Worked decision:</strong> stock for a tenant/SKU must never become negative and duplicate SKUs must be rejected. Write the invariant, choose a unique tenant/SKU constraint and an atomic conditional update inside the required transaction boundary, then verify two simultaneous decrements. A product catalog page may tolerate a deliberately stale read/cache; checkout cannot silently reuse that weaker contract. A different data model does not remove either invariant or its concurrency test.</p><p>References checked2026-10-22: <a href="https://www.mongodb.com/docs/manual/core/transactions/" target="_blank" rel="noreferrer">MongoDB transactions</a>, <a href="https://www.mongodb.com/docs/manual/reference/read-concern/" target="_blank" rel="noreferrer">MongoDB read concern</a>, <a href="https://neo4j.com/docs/operations-manual/current/database-internals/transaction-management/" target="_blank" rel="noreferrer">Neo4j transactions</a>, <a href="https://www.postgresql.org/docs/16/transaction-iso.html" target="_blank" rel="noreferrer">PostgreSQL16 isolation</a>, <a href="https://groups.csail.mit.edu/tds/papers/Gilbert/Brewer6.pdf" target="_blank" rel="noreferrer">Gilbert/Lynch CAP model</a>.</p><h2 id="separate-practice" tabindex="-1"><span class="hub-section-number">11 </span>Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “11 Separate practice”">​</a></h2><p>Use the <a href="./../../practice/engineering/design/Do_you_know_some_of_the_differences_of_non_relational_databases_and_relational_databases.html">focused acceptance and evidence requirements</a>. All learner practice remains outstanding.</p>',36)])])}const h=e(o,[["render",r]]);export{p as __pageData,h as default};
